<div class="admin-form-grid"><label>Project title <input name="title" required maxlength="180" value="<?= View::escape($project['title']??'') ?>"></label><label>URL slug <input name="slug" maxlength="200" placeholder="generated-from-title" value="<?= View::escape($project['slug']??'') ?>"><small>Use lowercase letters, numbers and hyphens.</small></label>
